SUB = {"fpr_diff": 0.15, "selrate_diff": 0.05}
SWP = {"schwelle": 0.6, "f1": 0.78, "paritaet_ok": True}
KST = {"input_eur": 0.06, "output_eur": 0.06, "gesamt_eur": 0.12}
r = responsible_report(SUB, SWP, KST, ["regel-detektor erkennt nur bekannte muster", "kein echtes llm"])
__check('bericht mit allen teilen', r == {"fpr_diff": 0.15, "selrate_diff": 0.05, "schwelle": 0.6, "f1": 0.78, "kosten_gesamt_eur": 0.12, "restrisiko": ["kein echtes llm", "regel-detektor erkennt nur bekannte muster"]})
for args, meldung in (
    (({}, SWP, KST, ["x"]), "subgruppen fehlen"),
    ((SUB, {"schwelle": 0.6, "f1": 0.78}, KST, ["x"]), "paritaet nicht geprueft"),
    ((SUB, SWP, {"input_eur": 0.06}, ["x"]), "kosten fehlen"),
    ((SUB, SWP, KST, []), "restrisiko fehlt"),
):
    try:
        responsible_report(*args)
        __check('verweigert: ' + meldung, False, 'kein ValueError')
    except ValueError as exc:
        __check('verweigert: ' + meldung, str(exc) == meldung)
