    responsible_report(SUB, {"schwelle": 0.6, "f1": 0.78, "paritaet_ok": False}, KST, ["x"])
    print("paritaet-false nicht verworfen")
except ValueError as exc:
    __check('paritaet false -> ValueError', str(exc) == "paritaet nicht geprueft")
